// Cloudflare Worker entry: the generated OpenNext handler, with headers that
// name the API's hosting provider removed, and an edge cache for public API
// responses (see lib/edge-cache.ts).
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore `.open-next/worker.js` is generated by `opennextjs-cloudflare build`
import handler from "./.open-next/worker.js";
import { withoutHostingHeaders } from "./lib/response-headers";
import { cacheableRequest, edgeCopy, fromEdge } from "./lib/edge-cache";

type Context = { waitUntil(promise: Promise<unknown>): void };
// The Cache API is unavailable on *.workers.dev; there `caches` is a no-op
// and every request simply goes to the origin.
const edge = () =>
  (globalThis as unknown as { caches?: { default?: Cache } }).caches?.default;

export default {
  async fetch(request: Request, env: unknown, ctx: Context) {
    const cache = cacheableRequest(request) ? edge() : undefined;
    const key = new Request(new URL(request.url).toString());
    const hit = cache ? await cache.match(key) : undefined;
    if (hit) return fromEdge(hit);
    const response = withoutHostingHeaders(
      await handler.fetch(request, env, ctx),
    );
    const copy = cache ? edgeCopy(response) : null;
    if (cache && copy) ctx.waitUntil(cache.put(key, copy));
    return response;
  },
};
